import { Router } from "express";
import { createProgressPhoto, deleteProgressPhoto, getProgressPhotoById, getProgressPhotos, updateProgressPhoto, } from "../controllers/progress-photo.controller";
import { requiredAuth } from "../middleware/auth.middleware";
import { requireRole } from "../middleware/role.middleware";
import { uploadImages } from "../middleware/upload.middleware";
const router = Router();
router.post("/", requiredAuth, requireRole("engineer", "supervisor", "admin"), uploadImages, createProgressPhoto);
router.get("/", requiredAuth, requireRole("client", "engineer", "supervisor", "admin"), getProgressPhotos);
router.get("/:id", requiredAuth, requireRole("client", "engineer", "supervisor", "admin"), getProgressPhotoById);
router.put("/:id", requiredAuth, requireRole("engineer", "supervisor", "admin"), uploadImages, updateProgressPhoto);
router.delete("/:id", requiredAuth, requireRole("engineer", "supervisor", "admin"), deleteProgressPhoto);
export default router;
